def insertion_point(xs, x):
    """Return the leftmost index at which ``x`` could be inserted into ``xs`` to keep it sorted.

    Equivalent to ``bisect.bisect_left(xs, x)``.
    """
    lo, hi = 0, len(xs)
    while lo < hi:
        mid = (lo + hi) // 2
        if xs[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo
